"""
OutputFormatter — renders SynthesisResult as structured markdown.
Zone-tagged, sectioned by dimension. Zero LLM calls.
"""


class OutputFormatter:
    def format(self, result) -> str:
        lines = []
        lines.append(f"# Decomposition Analysis: {result.query}")
        lines.append("")
        lines.append(self._summary_table(result))
        lines.append("")
        lines.append(self._dimension_details(result))
        lines.append("")
        if result.gaps:
            lines.append(self._gap_section(result))
            lines.append("")
        if result.path:
            lines.append(self._path_section(result))
            lines.append("")
        lines.append(self._meta_section(result))
        return "\n".join(lines)

    def _summary_table(self, result) -> str:
        lines = [
            "## Summary",
            "",
            f"**Overall Score:** {result.overall_score:.2f}",
            f"**Facts Used:** {result.facts_used}",
            f"**Zone Distribution:** [K]={result.facts_by_zone.get('K', 0)} "
            f"[T]={result.facts_by_zone.get('T', 0)} "
            f"[?]={result.facts_by_zone.get('?', 0)}",
            f"**LLM Calls in Synthesis:** {result.llm_calls_made}",
            "",
            "| Dimension | Score | Facts | Zone | Status |",
            "|-----------|-------|-------|------|--------|",
        ]
        for dim_name, ds in sorted(result.dimension_scores.items(), key=lambda x: -x[1].score):
            status = "covered" if ds.score >= 0.7 else "partial" if ds.score >= 0.4 else "GAP"
            lines.append(f"| {dim_name} | {ds.score:.2f} | {ds.fact_count} | [{ds.zone_tag}] | {status} |")
        return "\n".join(lines)

    def _dimension_details(self, result) -> str:
        lines = ["## Dimension Details", ""]
        for dim_name, ds in sorted(result.dimension_scores.items(), key=lambda x: -x[1].score):
            lines.append(f"### {dim_name} [{ds.zone_tag}] (score={ds.score:.2f})")
            lines.append(f"- Facts: {ds.fact_count}, Avg confidence: {ds.avg_confidence:.2f}")
            if ds.contradictions > 0:
                lines.append(f"- Contradictions: {ds.contradictions}")
            lines.append("")
        return "\n".join(lines)

    def _gap_section(self, result) -> str:
        lines = ["## Knowledge Gaps (ranked by priority)", ""]
        for gap in result.gaps:
            lines.append(f"### {gap.dimension} (priority={gap.priority:.2f}, score={gap.score:.2f})")
            lines.append(f"**Action:** {gap.suggested_action}")
            if gap.missing_queries:
                lines.append("**Missing queries:**")
                for q in gap.missing_queries[:3]:
                    lines.append(f"- {q}")
            lines.append("")
        return "\n".join(lines)

    def _path_section(self, result) -> str:
        lines = ["## Actionable Path", ""]
        for step in result.path:
            lines.append(
                f"{step.step_number}. [{step.zone_tag}] **{step.action}** "
                f"(confidence={step.confidence:.2f})"
            )
            lines.append(f"   {step.rationale}")
            if step.dependencies:
                lines.append(f"   Depends on: {', '.join(step.dependencies)}")
        return "\n".join(lines)

    def _meta_section(self, result) -> str:
        return (
            f"---\n"
            f"*Query type: {result.query_type} | "
            f"Dimensions: {len(result.dimension_scores)} | "
            f"LLM calls (synthesis): {result.llm_calls_made}*"
        )

