"""Tests for Micro-Decomposition Engine Phase 1: Decomposer + Dimension Registry."""

import pytest
from unittest.mock import MagicMock

from ..decomposer import Decomposer, DecompositionTree
from ..dimension_registry import (
    DIMENSION_REGISTRY, QUESTION_TYPE_DIMENSIONS, Dimension,
    get_dimensions, load_evolved_weights,
)
